local Singleton = import('Frame.Singleton')


---@class PreDownloadMgr
---@field GetInstance fun(self:PreDownloadMgr):PreDownloadMgr
local PreDownloadMgr = Class('PreDownloadMgr', Singleton)

function PreDownloadMgr:__init()
    ---@type PreDownloadComponent
    self._preDownloadComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PreDownloadComponent)
    self._loadCoLoader = {}
end

function PreDownloadMgr:__delete()
    self._preDownloadComponent = nil
    ---@param loader Engine.Modules.AbstractResourceLoader
    for k, loader in pairs(self._loadCoLoader or {}) do
        if not isNull(loader) then
            loader:Release()
        end
        self._loadCoLoader[k] = nil
    end
end

function PreDownloadMgr:InsetLoader(path, loader)
    if self._loadCoLoader[path] then
        self._loadCoLoader[path]:Release()
    end
    self._loadCoLoader[path] = loader
end
function PreDownloadMgr:PopupLoader(path)
    local loader = self._loadCoLoader[path]
    self._loadCoLoader[path] = nil
    return loader
end
function PreDownloadMgr:IsHasLoader(path)
    return self._loadCoLoader[path] ~= nil
end

---初始化数据
function PreDownloadMgr:InitPreDownloadData(data)
    local comp = self:GetPreDownloadComponent()
    comp:Initial(data)
end

---更新home数据
function PreDownloadMgr:UpdatePreDownloadData()
    GameUtils.Request(Interfaces.PreDownloadHome, {userId = self:GetUserId()}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self:InitPreDownloadData(response.data)
        Events.Broadcast(Constants.EventNames.PreDownloadDataUpdate)
    end)
end

---获取preDownloadComponent
---@return PreDownloadComponent
function PreDownloadMgr:GetPreDownloadComponent()
    return self._preDownloadComponent
end

---判断每日任务是否完成
---@param taskId integer 任务id
function PreDownloadMgr:IsDailyTaskFinished(taskId, targetNum)
    local comp = self:GetPreDownloadComponent()
    local taskProgress = comp:GetTaskProgress()

    return checkInt(taskProgress[tostring(taskId)]) >= checkInt(targetNum)

end

---判断猫球是否全服解锁
---@param geneId integer 基因id
---@return boolean 是否解锁
function PreDownloadMgr:JudgeCatUnlock(geneId)
    local data = self:GetCatGenes()
    for _, id in ipairs(data) do
        if checkInt(geneId) == checkInt(id) then
            return true
        end
    end
    return false
end

---获取个人解锁排名
---@param geneId integer 基因id
---@return integer 排名（未解锁返回0）
function PreDownloadMgr:GetPersonalUnlockRank(geneId)
    local comp = self:GetPreDownloadComponent()
    local data = comp:GetMyDiscoveredGenes()
    return checkInt(data[tostring(geneId)])
end

---获取userId
function PreDownloadMgr:GetUserId()
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if isNull(userComponent) then return end
    
    return userComponent.userInfo.userId
end

---获取key
function PreDownloadMgr:GetCatGenesDefine()
    return string.format('PreDownload_Cat_Genes_%s', tostring(self:GetUserId()))
end

---添加猫咪基因
---@return boolean 是否为new
function PreDownloadMgr:AddCatGene(geneId)
    if not geneId then return end

    local genesStr = CfUtils.GetLocalData(self:GetCatGenesDefine(), "")
    local genes = string.split2(genesStr, ";")

    if genesStr == '' then
        CfUtils.WriteLocalData(self:GetCatGenesDefine(), tostring(geneId))
    else
        CfUtils.WriteLocalData(self:GetCatGenesDefine(), genesStr .. ';' .. tostring(geneId))
    end
    
    for _, v in ipairs(genes) do
        if checkInt(v) == checkInt(geneId) then
            return false
        end
    end
    return true
end

---获取猫咪基因
function PreDownloadMgr:GetCatGenes()
    local genesStr = CfUtils.GetLocalData(self:GetCatGenesDefine(), "")
    local genes = string.split2(genesStr, ";")
    return genes
end

return PreDownloadMgr